insert into public.markets (id, slug, name, about, address, city, province, postal_code, lat, lng, geofence_radius_m, website, phone, email, tags, status, featured) values
  ('00000000-0000-0000-0000-000000000001', 'st-lawrence-market', 'St. Lawrence Market', 'Toronto''s landmark public market since 1803. Saturday farmers'' market downstairs, plus a year-round indoor hall of butchers, bakers, and produce stalls.', '93 Front Street East', 'Toronto', 'ON', 'M5E 1C3', 43.6491, -79.3716, 350, 'https://www.stlawrencemarket.com', '416-392-7219', null, ARRAY['indoor', 'year-round', 'produce', 'bakery', 'meat', 'cheese', 'transit', 'accessible'], 'published', true),
  ('00000000-0000-0000-0000-000000000002', 'evergreen-brick-works', 'Evergreen Brick Works Farmers'' Market', 'A Saturday market in the Don Valley with Ontario growers, bakers, and hot food, plus trails and the old brick kilns.', '550 Bayview Avenue', 'Toronto', 'ON', 'M4W 3X8', 43.6845, -79.3656, 300, 'https://www.evergreen.ca/evergreen-brick-works/markets/', '416-596-7670', null, ARRAY['outdoor', 'seasonal', 'organic', 'parking', 'family-friendly', 'produce'], 'published', false),
  ('00000000-0000-0000-0000-000000000003', 'byward-market', 'ByWard Market', 'Ottawa''s historic market district. Outdoor farm stalls in season, specialty shops year-round, and a dense block of food around the square.', '55 ByWard Market Square', 'Ottawa', 'ON', 'K1N 9C3', 45.4278, -75.6922, 400, 'https://www.byward-market.com', '613-562-3325', null, ARRAY['outdoor', 'indoor', 'year-round', 'produce', 'flowers', 'transit'], 'published', true),
  ('00000000-0000-0000-0000-000000000004', 'hamilton-farmers-market', 'Hamilton Farmers'' Market', 'A downtown indoor market that''s been feeding Hamilton since 1837 — produce, meat, cheese, and prepared food under one roof.', '35 York Boulevard', 'Hamilton', 'ON', 'L8R 3L4', 43.2567, -79.8696, 200, 'https://hamiltonfarmersmarket.ca', '905-546-2096', null, ARRAY['indoor', 'year-round', 'produce', 'meat', 'accessible', 'transit'], 'published', false),
  ('00000000-0000-0000-0000-000000000005', 'kitchener-market', 'Kitchener Market', 'Saturday is the big farm day; Thursday is a smaller indoor market. German heritage stalls sit beside new Canadian growers.', '300 King Street East', 'Kitchener', 'ON', 'N2G 2L3', 43.4493, -80.4885, 250, 'https://www.kitchenermarket.ca', '519-741-2287', null, ARRAY['indoor', 'outdoor', 'year-round', 'parking', 'bakery', 'produce'], 'published', false),
  ('00000000-0000-0000-0000-000000000006', 'covent-garden-market', 'Covent Garden Market', 'London''s year-round market hall with a Saturday farmers'' market spilling onto the square.', '130 King Street', 'London', 'ON', 'N6A 1C5', 42.9826, -81.2497, 250, 'https://www.coventmarket.com', '519-439-3921', null, ARRAY['indoor', 'year-round', 'produce', 'coffee', 'accessible'], 'published', false),
  ('00000000-0000-0000-0000-000000000007', 'granville-island-public-market', 'Granville Island Public Market', 'Vancouver''s waterfront public market: BC produce, fish, cheese, and baked goods in a shed on the creek, seven days a week.', '1689 Johnston Street', 'Vancouver', 'BC', 'V6H 3R9', 49.2712, -123.134, 350, 'https://granvilleisland.com/public-market', '604-666-6655', null, ARRAY['indoor', 'year-round', 'produce', 'seafood', 'bakery', 'transit', 'family-friendly'], 'published', true),
  ('00000000-0000-0000-0000-000000000008', 'trout-lake-farmers-market', 'Trout Lake Farmers Market', 'East Vancouver Saturday market beside John Hendry Park. Heavy on organic produce, flowers, and ready-to-eat.', '3350 Victoria Drive', 'Vancouver', 'BC', 'V5N 4M4', 49.2556, -123.062, 220, 'https://www.eatlocal.org/markets/trout-lake-farmers-market/', null, null, ARRAY['outdoor', 'seasonal', 'organic', 'produce', 'flowers', 'family-friendly'], 'published', false),
  ('00000000-0000-0000-0000-000000000009', 'moss-street-market', 'Moss Street Market', 'Victoria''s neighbourhood Saturday market on Fairfield — growers from the Island and the Saanich Peninsula.', '1440 Fairfield Road', 'Victoria', 'BC', 'V8S 1E5', 48.4135, -123.346, 200, 'https://mossstreetmarket.com', null, null, ARRAY['outdoor', 'seasonal', 'organic', 'produce', 'crafts'], 'published', false),
  ('00000000-0000-0000-0000-000000000010', 'calgary-farmers-market', 'Calgary Farmers'' Market', 'A large indoor market south of downtown with Alberta ranchers, bakers, and a full food hall. Open four days a week.', '510 77 Avenue SE', 'Calgary', 'AB', 'T2H 1C3', 51.0133, -114.0465, 400, 'https://calgaryfarmersmarket.ca', '403-240-9113', null, ARRAY['indoor', 'year-round', 'parking', 'meat', 'produce', 'prepared-food', 'accessible'], 'published', true),
  ('00000000-0000-0000-0000-000000000011', 'old-strathcona-farmers-market', 'Old Strathcona Farmers'' Market', 'Edmonton''s Saturday market in the historic bus barns — 130+ vendors, year-round.', '10310 83 Avenue NW', 'Edmonton', 'AB', 'T6E 2C6', 53.518, -113.497, 250, 'https://osfm.ca', '780-439-1844', null, ARRAY['indoor', 'year-round', 'produce', 'crafts', 'bakery', 'parking'], 'published', false),
  ('00000000-0000-0000-0000-000000000012', 'marche-jean-talon', 'Marché Jean-Talon', 'North America''s largest open-air market, in Little Italy. Quebec farms on the outside, specialty shops in the interior.', '7070 Avenue Henri-Julien', 'Montreal', 'QC', 'H2S 3S3', 45.5369, -73.6146, 400, 'https://www.marchespublics-mtl.com/marches/jean-talon/', '514-277-1588', null, ARRAY['outdoor', 'indoor', 'year-round', 'produce', 'flowers', 'transit', 'family-friendly'], 'published', true),
  ('00000000-0000-0000-0000-000000000013', 'marche-atwater', 'Marché Atwater', 'A 1933 art-deco market on the Lachine Canal. Butchers and cheese shops inside, produce stalls along the canal in summer.', '138 Avenue Atwater', 'Montreal', 'QC', 'H4C 2G3', 45.4795, -73.5764, 280, 'https://www.marchespublics-mtl.com/marches/atwater/', '514-937-7754', null, ARRAY['indoor', 'outdoor', 'year-round', 'meat', 'cheese', 'produce', 'transit'], 'published', false),
  ('00000000-0000-0000-0000-000000000014', 'halifax-seaport-farmers-market', 'Halifax Seaport Farmers'' Market', 'North America''s oldest continuously operating farmers'' market, now in a waterfront shed with solar roof and 250 vendors on Saturday.', '1209 Marginal Road', 'Halifax', 'NS', 'B3H 4P8', 44.6416, -63.5684, 300, 'https://halifaxfarmersmarket.com', '902-492-4043', null, ARRAY['indoor', 'year-round', 'produce', 'seafood', 'crafts', 'accessible'], 'published', true),
  ('00000000-0000-0000-0000-000000000015', 'saint-john-city-market', 'Saint John City Market', 'Canada''s oldest continuing farmers'' market (1876), under a hull-shaped roof in uptown Saint John.', '47 Charlotte Street', 'Saint John', 'NB', 'E2L 2H8', 45.2733, -66.0628, 180, 'https://www.sjcitymarket.ca', '506-658-2820', null, ARRAY['indoor', 'year-round', 'produce', 'seafood', 'accessible'], 'published', false),
  ('00000000-0000-0000-0000-000000000016', 'boyce-farmers-market', 'Boyce Farmers Market', 'Fredericton''s Saturday institution — hundreds of stalls of NB produce, baking, and crafts.', '665 George Street', 'Fredericton', 'NB', 'E3B 1K4', 45.9636, -66.6431, 250, 'https://www.boycefarmersmarket.com', '506-451-1815', null, ARRAY['indoor', 'outdoor', 'year-round', 'produce', 'crafts', 'parking'], 'published', false),
  ('00000000-0000-0000-0000-000000000017', 'the-forks-market', 'The Forks Market', 'Winnipeg''s meeting of the rivers. A year-round market hall with prairie vendors and a Saturday farmers'' market outside in season.', '1 Forks Market Road', 'Winnipeg', 'MB', 'R3C 4L9', 49.8875, -97.1306, 350, 'https://www.theforks.com', '204-957-7618', null, ARRAY['indoor', 'year-round', 'prepared-food', 'produce', 'family-friendly', 'parking'], 'published', false),
  ('00000000-0000-0000-0000-000000000018', 'regina-farmers-market', 'Regina Farmers'' Market', 'Saskatchewan growers on a downtown square through the warm months, then indoors for winter Saturday markets.', 'Cornwall Street & 11th Avenue', 'Regina', 'SK', 'S4P 3S7', 50.4547, -104.6067, 220, 'https://www.reginafarmersmarket.ca', null, null, ARRAY['outdoor', 'seasonal', 'produce', 'bakery', 'crafts'], 'published', false),
  ('00000000-0000-0000-0000-000000000019', 'saskatoon-farmers-market', 'Saskatoon Farmers'' Market', 'A year-round market in Riversdale with prairie produce, baking, and a courtyard when the weather allows.', '414 Avenue A South', 'Saskatoon', 'SK', 'S7M 5M4', 52.1255, -106.6598, 220, 'https://www.saskatoonfarmersmarket.com', '306-384-6262', null, ARRAY['indoor', 'outdoor', 'year-round', 'produce', 'parking'], 'published', false),
  ('00000000-0000-0000-0000-000000000020', 'charlottetown-farmers-market', 'Charlottetown Farmers'' Market', 'Saturday morning on Belvedere — PEI potatoes, seafood, baking, and a full breakfast crowd.', '100 Belvedere Avenue', 'Charlottetown', 'PE', 'C1A 9M2', 46.258, -63.143, 200, 'https://www.charlottetownfarmersmarket.com', null, null, ARRAY['indoor', 'year-round', 'produce', 'seafood', 'parking'], 'published', false),
  ('00000000-0000-0000-0000-000000000021', 'st-johns-farmers-market', 'St. John''s Farmers'' Market', 'Newfoundland makers and growers in the Lion''s Club building on Saturday, with a strong craft and prepared-food bench.', '245 Freshwater Road', 'St. John''s', 'NL', 'A1C 2N6', 47.5615, -52.724, 200, 'https://www.stjohnsfarmersmarket.org', null, null, ARRAY['indoor', 'year-round', 'crafts', 'produce', 'prepared-food'], 'published', false),
  ('00000000-0000-0000-0000-000000000022', 'fireweed-community-market', 'Fireweed Community Market', 'Whitehorse''s Thursday market in Shipyards Park through summer — Yukon growers, makers, and food trucks under the midnight-adjacent sun.', 'Shipyards Park, 1 Waterfront Place', 'Whitehorse', 'YT', 'Y1A 1A3', 60.7247, -135.0568, 250, 'https://www.fireweedmarket.ca', null, null, ARRAY['outdoor', 'seasonal', 'produce', 'crafts', 'family-friendly'], 'published', false)
