insert into public.vendors (id, slug, name, about, website, phone, tags, status) values
  ('00000000-0000-0000-0000-000000000101', 'red-barn-roots', 'Red Barn Roots', 'Certified organic vegetables from a 40-acre plot north of Toronto. CSA boxes and Saturday stall.', 'https://example.com/red-barn-roots', '905-555-0142', ARRAY['produce', 'organic'], 'published'),
  ('00000000-0000-0000-0000-000000000102', 'maple-hearth-bakery', 'Maple Hearth Bakery', 'Naturally leavened breads and butter pastries. Ontario wheat, baked overnight.', null, '416-555-0198', ARRAY['bakery'], 'published'),
  ('00000000-0000-0000-0000-000000000103', 'loon-lake-honey', 'Loon Lake Honey', 'Small-lot honey from hives on the Canadian Shield. Wildflower, basswood, and a spring dandelion run.', null, null, ARRAY['honey'], 'published'),
  ('00000000-0000-0000-0000-000000000104', 'twin-river-dairy', 'Twin River Dairy', 'Raw-milk style cheeses made from a closed herd in Oxford County. Clothbound cheddar and a weekly fresh chèvre.', 'https://example.com/twin-river', '519-555-0110', ARRAY['cheese'], 'published'),
  ('00000000-0000-0000-0000-000000000105', 'shoreline-smokehouse', 'Shoreline Smokehouse', 'Hot-smoked Great Lakes trout and a peppery summer sausage. Cooler packed, card accepted.', null, '647-555-0166', ARRAY['seafood', 'meat'], 'published'),
  ('00000000-0000-0000-0000-000000000106', 'kootenay-greens', 'Kootenay Greens', 'Greenhouse and field veg from Creston. Heavy on salad mixes and greenhouse tomatoes that actually taste like tomatoes.', null, null, ARRAY['produce', 'organic'], 'published'),
  ('00000000-0000-0000-0000-000000000107', 'island-shellfish', 'Island Shellfish', 'Live oysters, clams, and spot prawns in season from Baynes Sound.', 'https://example.com/island-shellfish', '250-555-0133', ARRAY['seafood'], 'published'),
  ('00000000-0000-0000-0000-000000000108', 'crowfoot-flowers', 'Crowfoot Flowers', 'Seasonal cuts from a Calgary-area plot. No imports, no dyed mums.', null, null, ARRAY['flowers'], 'published'),
  ('00000000-0000-0000-0000-000000000109', 'prairie-loaf', 'Prairie Loaf', 'Red Fife and durum breads milled in-house in Edmonton.', null, '780-555-0177', ARRAY['bakery'], 'published'),
  ('00000000-0000-0000-0000-000000000110', 'gaspesie-catch', 'Gaspésie Catch', 'Snow crab, shrimp, and salted cod from a family boat working the Gulf.', null, '418-555-0121', ARRAY['seafood'], 'published'),
  ('00000000-0000-0000-0000-000000000111', 'ile-dorleans-preserves', 'Île d''Orléans Preserves', 'Strawberry, apple, and elderflower jars from the island. No pectin gymnastics.', null, null, ARRAY['preserves'], 'published'),
  ('00000000-0000-0000-0000-000000000112', 'fundy-orchard', 'Fundy Orchard', 'Apples, pears, and a dry cider from the Annapolis Valley.', 'https://example.com/fundy-orchard', '902-555-0188', ARRAY['produce'], 'published'),
  ('00000000-0000-0000-0000-000000000113', 'red-river-meats', 'Red River Meats', 'Pasture beef and pork from south of Winnipeg. Frozen packs and a Saturday sausage grill.', null, '204-555-0144', ARRAY['meat'], 'published'),
  ('00000000-0000-0000-0000-000000000114', 'sable-island-wool', 'Sable Shore Knit', 'PEI wool hats and mitts. Not produce — still a market regular.', null, null, ARRAY['crafts'], 'published'),
  ('00000000-0000-0000-0000-000000000115', 'yukon-gold-plot', 'Yukon Gold Plot', 'Short-season greens, greenhouse cucumbers, and a ferocious garlic from just outside Whitehorse.', null, null, ARRAY['produce'], 'published')
